"""
Pydantic schemas for EDS antenna entities (physical and logical).

Antenna models use CellContextFieldsMixin for mu_iid/eid and cell_iid/eid,
but define location_iid/eid locally because their JSON paths are flat
("location_iid") rather than nested ("location.iid").
"""

from typing import Optional

from pydantic import Field

from pipeline_app.schemas._mixins import CellContextFieldsMixin


class CellPhysicalAntennaModel(CellContextFieldsMixin):
    location_iid: Optional[str] = Field(None, json_schema_extra={"json_path": "location_iid"})
    location_eid: Optional[int] = Field(None, json_schema_extra={"json_path": "location_eid"})
    spatialdiversity: Optional[bool] = Field(None, json_schema_extra={"json_path": "spatialDiversity"})
    azimuth: Optional[float] = Field(None, json_schema_extra={"json_path": "azimuth"})
    tilt: Optional[float] = Field(None, json_schema_extra={"json_path": "tilt"})
    twist: Optional[float] = Field(None, json_schema_extra={"json_path": "twist"})
    height: Optional[float] = Field(None, json_schema_extra={"json_path": "height"})
    heightpredoffset: Optional[float] = Field(None, json_schema_extra={"json_path": "heightPredOffset"})
    heightpred: Optional[float] = Field(None, json_schema_extra={"json_path": "heightPred"})
    antennatype_ro: Optional[str] = Field(None, json_schema_extra={"json_path": "antennaType_RO"})
    antennadevice_iid: Optional[str] = Field(None, json_schema_extra={"json_path": "antennaDevice.iid"})
    antennadevice_eid: Optional[int] = Field(None, json_schema_extra={"json_path": "antennaDevice.eid"})
    masterpattern1_iid: Optional[str] = Field(None, json_schema_extra={"json_path": "masterPattern1.iid"})
    masterpattern1_eid: Optional[float] = Field(None, json_schema_extra={"json_path": "masterPattern1.eid"})
    masterpattern2_iid: Optional[str] = Field(None, json_schema_extra={"json_path": "masterPattern2.iid"})
    masterpattern2_eid: Optional[float] = Field(None, json_schema_extra={"json_path": "masterPattern2.eid"})
    masterpattern3_iid: Optional[str] = Field(None, json_schema_extra={"json_path": "masterPattern3.iid"})
    masterpattern3_eid: Optional[float] = Field(None, json_schema_extra={"json_path": "masterPattern3.eid"})
    masterpattern4_iid: Optional[str] = Field(None, json_schema_extra={"json_path": "masterPattern4.iid"})
    masterpattern4_eid: Optional[float] = Field(None, json_schema_extra={"json_path": "masterPattern4.eid"})
    masterpattern5_iid: Optional[str] = Field(None, json_schema_extra={"json_path": "masterPattern5.iid"})
    masterpattern5_eid: Optional[float] = Field(None, json_schema_extra={"json_path": "masterPattern5.eid"})
    masterpattern6_iid: Optional[str] = Field(None, json_schema_extra={"json_path": "masterPattern6.iid"})
    masterpattern6_eid: Optional[float] = Field(None, json_schema_extra={"json_path": "masterPattern6.eid"})
    masterpattern7_iid: Optional[str] = Field(None, json_schema_extra={"json_path": "masterPattern7.iid"})
    masterpattern7_eid: Optional[float] = Field(None, json_schema_extra={"json_path": "masterPattern7.eid"})
    masterpattern8_iid: Optional[str] = Field(None, json_schema_extra={"json_path": "masterPattern8.iid"})
    masterpattern8_eid: Optional[float] = Field(None, json_schema_extra={"json_path": "masterPattern8.eid"})
    abslocation_longitude: Optional[float] = Field(None, json_schema_extra={"json_path": "absLocation.longitude"})
    abslocation_latitude: Optional[float] = Field(None, json_schema_extra={"json_path": "absLocation.latitude"})
    abslocation_epsg: Optional[int] = Field(None, json_schema_extra={"json_path": "absLocation.epsg"})
    location_x: Optional[float] = Field(None, json_schema_extra={"json_path": "location.x"})
    location_y: Optional[float] = Field(None, json_schema_extra={"json_path": "location.y"})
    location_z: Optional[float] = Field(None, json_schema_extra={"json_path": "location.z"})
    location_relative: Optional[str] = Field(None, json_schema_extra={"json_path": "location.relative"})
    location_epsg: Optional[int] = Field(None, json_schema_extra={"json_path": "location.epsg"})
    constraints_antennadevicefixed: Optional[bool] = Field(None, json_schema_extra={"json_path": "constraints.antennaDeviceFixed"})
    constraints_azimuthfixed: Optional[bool] = Field(None, json_schema_extra={"json_path": "constraints.azimuthFixed"})
    constraints_heightfixed: Optional[bool] = Field(None, json_schema_extra={"json_path": "constraints.heightFixed"})
    constraints_mechanicaltiltfixed: Optional[bool] = Field(None, json_schema_extra={"json_path": "constraints.mechanicalTiltFixed"})
    constraints_useforbiddenazimuth: Optional[bool] = Field(None, json_schema_extra={"json_path": "constraints.useForbiddenAzimuth"})
    constraints_forbiddenazimuthfrom: Optional[int] = Field(None, json_schema_extra={"json_path": "constraints.forbiddenAzimuthFrom"})
    constraints_forbiddenazimuthto: Optional[int] = Field(None, json_schema_extra={"json_path": "constraints.forbiddenAzimuthTo"})
    constraints_minmechanicaltilt_constrained: Optional[bool] = Field(None, json_schema_extra={"json_path": "constraints.minMechanicalTilt.constrained"})
    constraints_minmechanicaltilt_value: Optional[int] = Field(None, json_schema_extra={"json_path": "constraints.minMechanicalTilt.value"})
    constraints_maxmechanicaltilt_constrained: Optional[bool] = Field(None, json_schema_extra={"json_path": "constraints.maxMechanicalTilt.constrained"})
    constraints_maxmechanicaltilt_value: Optional[int] = Field(None, json_schema_extra={"json_path": "constraints.maxMechanicalTilt.value"})
    constraints_mechanicaltiltstep_constrained: Optional[bool] = Field(None, json_schema_extra={"json_path": "constraints.mechanicalTiltStep.constrained"})
    constraints_mechanicaltiltstep_value: Optional[int] = Field(None, json_schema_extra={"json_path": "constraints.mechanicalTiltStep.value"})
    availsyncretgrps: Optional[str] = Field(None, json_schema_extra={"json_path": "availSyncRetGrps"})
    abslocation_dtmovr: Optional[float] = Field(None, json_schema_extra={"json_path": "absLocation.dtmOvr"})
    abslocation_dtmovrprop: Optional[float] = Field(None, json_schema_extra={"json_path": "absLocation.dtmOvrProp"})


class CellLogicalAntennaModel(CellContextFieldsMixin):
    location_iid: Optional[str] = Field(None, json_schema_extra={"json_path": "location_iid"})
    location_eid: Optional[int] = Field(None, json_schema_extra={"json_path": "location_eid"})
